exercises.solution:
def square(number):
    if number == 0:
        raise ValueError('square must be between 1 and 64')
    elif number < 0:
        raise ValueError('square must be between 1 and 64')
    elif number > 64:
        raise ValueError('square must be between 1 and 64')

    return 2 ** (number - 1)


def total():
    return (2 ** 64) - 1

