        self.assertIs(is_pangram('abcdefghijklm ABCDEFGHIJKLM'), False)

    def test_sentence_without_lower_bound(self):
        self.assertIs(is_pangram('bcdefghijklmnopqrstuvwxyz'), False)

    def test_sentence_without_upper_bound(self):
