from itertools import permutations
from functools import reduce


def swap(item_1, item_2):
    return (item_2, item_1)


def build_chain(chain, domino):
    if chain is not None:
        last = chain[-1]
        if len(chain) == 1 and last[0] == domino[0]:
            return [swap(*last), domino]
        elif len(chain) == 1 and last[0] == domino[1]:
            return [swap(*last), swap(*domino)]
        elif last[1] == domino[0]:
            return chain + [domino]
        elif last[1] == domino[1]:
            return chain + [swap(*domino)]
    return None


def can_chain(dominoes):
    if not any(dominoes):
        return []
    for perm in permutations(dominoes):
        chain = reduce(build_chain, perm[1:], [perm[0]])
        if chain is not None and chain[0][0] == chain[-1][1]:
            return chain
    return None

def tree_from_traversals(preorder, inorder):
    if len(preorder) != len(inorder):
        raise ValueError('traversals must have the same length')
    if set(preorder) != set(inorder):
        raise ValueError('traversals must have the same elements')
    if len(set(preorder)) != len(preorder) != len(set(inorder)):
        raise ValueError('traversals must contain unique items')
    if not preorder:
        return {}

    value = preorder.pop(0)
    index = inorder.index(value)
    left_inorder, right_inorder = inorder[:index], inorder[index+1:]

    left_preorder = [idx for idx in preorder if idx in left_inorder]
    right_preorder = [idx for idx in preorder if idx in right_inorder]

    left = tree_from_traversals(left_preorder, left_inorder)
    right = tree_from_traversals(right_preorder, right_inorder)

    return {'v': value, 'l': left, 'r': right}

from collections import Counter

PER_BOOK = 800.00
PER_GROUP = {
    1: 1 * PER_BOOK * 1.00,
    2: 2 * PER_BOOK * 0.95,
    3: 3 * PER_BOOK * 0.90,
    4: 4 * PER_BOOK * 0.80,
    5: 5 * PER_BOOK * 0.75,
}


def _total(basket):
    volumes = Counter(basket)
    price = len(basket) * PER_BOOK
    for size in range(len(volumes), 1, -1):
        group = volumes - Counter(k for k, _ in volumes.most_common(size))
        group_books = sorted(group.elements())
        price = min(price, PER_GROUP[size] + _total(group_books))
    return price


def total(basket):
    if not basket:
        return 0
    return _total(sorted(basket))

